    +'</div>';
   var content=tab==='timeline'?timelineView(g):tab==='followups'?followupsView(g):tab==='cadence'?cadenceView(g):tab==='outcomes'?outcomesView(g):tab==='analytics'?analyticsView(g):tab==='history'?historyView(g):commandView(g);
   return '<div class="ca3-shell">'+hero+kpis+tabBar(tab)+content+'</div>'+modalHTML(g)
