 window._rp2CRMActivityDraw=function(){
  if(typeof Chart!=='function')return;
  if(['cadence','outcomes','analytics','history'].indexOf(window._rp2CRMActivityTab)<0)return;
  var canvas=document.getElementById('ca3-chart');if(!canvas)return;var g=build();
  if(_rp2.crmActivityChart){try{_rp2.crmActivityChart.destroy()}catch(e){}}
  if(window._rp2CRMActivityTab==='cadence'){
   var rows=g.cadence.slice(0,20);
   _rp2.crmActivityChart=new Chart(canvas.getContext('2d'),{type:'bar',data:{labels:rows.map(function(x){return x.company}),datasets:[{label:'Cadence score',data:rows.map(function(x){return x.score}),backgroundColor:'rgba(0,175,239,.68)',borderRadius:6}]},options:{indexAxis:'y',responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{beginAtZero:true,max:100,ticks:{color:'#8b95a7'},grid:{color:'rgba(255,255,255,.05)'}},y:{ticks:{color:'#aab4c6',font:{size:8}},grid:{display:false}}}}})
  }else if(window._rp2CRMActivityTab==='outcomes'){
   var out=g.stats.outcomes.slice(0,12);_rp2.crmActivityChart=new Chart(canvas.getContext('2d'),{type:'bar',data:{labels:out.map(function(x){return x.name}),datasets:[{label:'Activities',data:out.map(function(x){return x.value}),backgroundColor:'rgba(78,214,163,.68)',borderRadius:6}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{ticks:{color:'#8b95a7',font:{size:8},maxRotation:25},grid:{display:false}},y:{beginAtZero:true,ticks:{color:'#8b95a7',precision:0},grid:{color:'rgba(255,255,255,.05)'}}}}})
  }else if(window._rp2CRMActivityTab==='analytics'){
   var types=g.stats.types.slice(0,12);_rp2.crmActivityChart=new Chart(canvas.getContext('2d'),{type:'bar',data:{labels:types.map(function(x){return x.name}),datasets:[{label:'Activities',data:types.map(function(x){return x.value}),backgroundColor:'rgba(245,190,100,.68)',borderRadius:6}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{ticks:{color:'#8b95a7',font:{size:8},maxRotation:20},grid:{display:false}},y:{beginAtZero:true,ticks:{color:'#8b95a7',precision:0},grid:{color:'rgba(255,255,255,.05)'}}}}})
  }else{
   var dates=[];arr(g.view.data.events).forEach(function(e){var d=dt(e.at);if(d)dates.push(d)});var map={};dates.sort(function(a,b){return a-b}).forEach(function(d){var k=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');map[k]=(map[k]||0)+1});var total=0,rows2=[];Object.keys(map).sort().forEach(function(k){total+=map[k];rows2.push({label:k,value:total})});if(!rows2.length)return;
   _rp2.crmActivityChart=new Chart(canvas.getContext('2d'),{type:'line',data:{labels:rows2.map(function(x){return x.label}),datasets:[{label:'Cumulative audit events',data:rows2.map(function(x){return x.value}),borderColor:'#00AFEF',backgroundColor:'rgba(0,175,239,.12)',fill:true,pointRadius:3,tension:.25}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{ticks:{color:'#8b95a7'},grid:{display:false}},y:{beginAtZero:true,ticks:{color:'#8b95a7',precision:0},grid:{color:'rgba(255,255,255,.05)'}}}}})
  }
 }

